inline const FontGlyphMetric* FindFontGlyph(uint32_t cp) {
    for (size_t i = 0; i < FONT_GLYPH_COUNT; ++i) {
        if (g_fontGlyphs[i].codepoint == cp) return &g_fontGlyphs[i];
    }
    return nullptr;
}

inline void DecompressFontAtlas(uint8_t* dst) {
    size_t inIdx = 0, outIdx = 0;
    while (inIdx < 76010 && outIdx < 524288) {
        uint8_t count = g_fontAtlasRLE[inIdx++];
        uint8_t val = g_fontAtlasRLE[inIdx++];
        for (uint8_t c = 0; c < count && outIdx < FONT_RAW_SIZE; ++c) {
            dst[outIdx++] = val;
        }
    }
}
